with ins as (insert into public.artist_discography (artist_slug,artist_id,title,release_type,release_date,year,label,source_url) select x.s,a.id,x.ti,x.ty,x.d::date,x.y,x.l,x.u from json_to_recordset('[{"s":"prismer","ti":"Babel (on SUCHI SELECTS)","ty":"compilation","y":2021,"d":"2021-12-16","l":"boxout.fm Recordings","u":"https://boxoutfm.bandcamp.com/track/prismer-babel"},{"s":"prismer","ti":"Rushh (on Reel Small World: India)","ty":"compilation","y":2022,"d":"2022-10-07","l":"Reel Long Overdub","u":"https://reellongoverdub.bandcamp.com/album/reel-small-world-india"},{"s":"spiralynk","ti":"Sinetific Noise","ty":"single","y":2020,"d":"2020-04-21","l":null,"u":"https://spiralynk.bandcamp.com/track/sinetific-noise"},{"s":"spiralynk","ti":"Obfuscate","ty":"single","y":2020,"d":"2020-04-21","l":null,"u":"https://spiralynk.bandcamp.com/track/obfuscate"},{"s":"spiralynk","ti":"Static Variable","ty":"single","y":2020,"d":"2020-04-21","l":null,"u":"https://spiralynk.bandcamp.com/track/static-variable"},{"s":"spiralynk","ti":"InSnTnT (on Social Isolation compilation)","ty":"compilation","y":2020,"d":null,"l":"Social Isolation","u":"https://www.youtube.com/watch?v=DC0iv8IIV98"},{"s":"spiralynk","ti":"Asthir (on Social Isolation, second edition)","ty":"compilation","y":2020,"d":null,"l":"Social Isolation","u":"https://www.youtube.com/watch?v=p798Fi8JGkU"},{"s":"spiralynk","ti":"Liminal Rift EP","ty":"ep","y":2025,"d":"2025-05-18","l":"Antariksh Records","u":"https://antarikshrecords.bandcamp.com/album/liminal-rift-ep"},{"s":"spiralynk","ti":"infract[ion] (on Algorave India Compilation One)","ty":"compilation","y":2025,"d":"2025-09-26","l":"Antariksh Records","u":"https://antarikshrecords.bandcamp.com/album/algorave-india-compilation-one"}]'::json) as x(s text,ti text,ty text,y int,d text,l text,u text) join public.artists a on a.slug=x.s where not exists (select 1 from public.artist_discography d where d.artist_slug=x.s and lower(d.title)=lower(x.ti)) on conflict do nothing returning 1) select count(*) from ins;